#!/usr/bin/env node
/**
 * Turns the human-editable prompt files in `prompts/*.md` into a typed module the
 * server and the offline scripts both import, so a prompt change is a reviewed
 * diff in one place and can never drift between runtime and tooling.
 *
 * Usage:
 *   node scripts/build-prompts.mjs           # write src/lib/ai/prompts.generated.ts
 *   node scripts/build-prompts.mjs --check   # fail if the generated file is stale
 */
import { readFileSync, readdirSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

const ROOT = resolve(import.meta.dirname, "..");
const PROMPT_DIR = join(ROOT, "prompts");
const OUT = join(ROOT, "src", "lib", "ai", "prompts.generated.ts");

function parseFrontMatter(source) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(source);
  if (!match) return { meta: {}, body: source.trim() };
  const meta = {};
  for (const line of match[1].split(/\r?\n/)) {
    const at = line.indexOf(":");
    if (at === -1) continue;
    meta[line.slice(0, at).trim()] = line.slice(at + 1).trim().replace(/^["']|["']$/g, "");
  }
  return { meta, body: source.slice(match[0].length).trim() };
}

const files = readdirSync(PROMPT_DIR).filter((name) => name.endsWith(".md")).sort();
if (files.length === 0) {
  console.error("No prompt files found in prompts/.");
  process.exit(1);
}

const entries = files.map((file) => {
  const { meta, body } = parseFrontMatter(readFileSync(join(PROMPT_DIR, file), "utf8"));
  const id = meta.id ?? file.replace(/\.md$/, "");
  if (!meta.version) throw new Error(`${file} is missing a "version" in its front matter.`);
  if (!body) throw new Error(`${file} has no prompt body.`);
  return { id, version: Number(meta.version), model: meta.model ?? "", output: meta.output ?? "text", file, body };
});

const banner = `// AUTO-GENERATED by scripts/build-prompts.mjs — do not edit by hand.
// Edit the matching file in prompts/ and re-run: node scripts/build-prompts.mjs
`;

const literal = (value) => `\`${String(value).replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${")}\``;

const generated = `${banner}
export type PromptId = ${entries.map((entry) => JSON.stringify(entry.id)).join(" | ")};

export type Prompt = {
  id: PromptId;
  version: number;
  model: string;
  output: string;
  source: string;
  text: string;
};

export const PROMPTS: Record<PromptId, Prompt> = {
${entries
  .map(
    (entry) => `  ${JSON.stringify(entry.id)}: {
    id: ${JSON.stringify(entry.id)},
    version: ${entry.version},
    model: ${JSON.stringify(entry.model)},
    output: ${JSON.stringify(entry.output)},
    source: ${JSON.stringify(`prompts/${entry.file}`)},
    text: ${literal(entry.body)},
  },`,
  )
  .join("\n")}
} as const;

export function getPrompt(id: PromptId): Prompt {
  const prompt = PROMPTS[id];
  if (!prompt) throw new Error(\`Unknown prompt: \${id}\`);
  return prompt;
}
`;

const current = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
const stale = current !== generated;

if (process.argv.includes("--check")) {
  if (stale) {
    console.error("✖ src/lib/ai/prompts.generated.ts is stale — run: node scripts/build-prompts.mjs");
    process.exit(1);
  }
  console.log(`✓ prompts in sync (${entries.length} prompt(s)).`);
  process.exit(0);
}

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, generated, "utf8");
console.log(`✓ wrote src/lib/ai/prompts.generated.ts (${entries.length} prompt(s)${stale ? "" : ", unchanged"}).`);
for (const entry of entries) {
  console.log(`  - ${entry.id} v${entry.version} (${entry.body.length} chars) from prompts/${entry.file}`);
}
